from collections import Counter

def majority_vote(answers: list) -> str:
    """Return the most common answer; ties broken by first occurrence in answers."""
    counts = Counter(answers)
    max_count = max(counts.values())
    for a in answers:
        if counts[a] == max_count:
            return a

print(majority_vote(['42', '41', '42', '42', '40']))
